import { afterAll, describe, expect, it, vi } from "vitest";
import { mkdtempSync, rmSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";

const root = mkdtempSync(join(tmpdir(), "cc-verify07-"));
vi.mock("../../src/lib/paths.js", () => ({
  getHomeDir: () => join(root, "home"),
  getClaudeProjectStorageDir: () => null,
  getStatePath: () => join(root, "home", "state"),
  getMachineSecurityAnchorDir: () => join(root, "security"),
}));

const store = await import("../../src/harness/jsonl-session-store.js");
const { readSessionTranscriptHistory } = await import(
  "../../src/lib/session-transcript-history.js"
);

afterAll(() => rmSync(root, { recursive: true, force: true }));

function start(id, count = 8) {
  store.startSession(id, { provider: "test", model: "test" });
  for (let i = 0; i < count; i++) {
    store.appendUserMessage(id, `question-${i}: ${"x".repeat(90)}`);
    store.appendAssistantMessage(id, `answer-${i}: ${"y".repeat(90)}`);
  }
}

function ids(page) {
  return page.messages.map((m) => m.id);
}

describe("persistent body pagination boundary (verify-07)", () => {
  it("walks forward cursors across pages covering every row exactly once", () => {
    // 3 user + 3 assistant pairs => 6 display rows, force pages of 2.
    const id = "verify-07-walk";
    start(id, 3);
    const first = readSessionTranscriptHistory(id, { limit: 2 });
    expect(first.messages).toHaveLength(2);

    const collected = [...ids(first)];
    let cursor = first.nextCursor;
    while (cursor) {
      const page = readSessionTranscriptHistory(id, { limit: 2, cursor });
      collected.push(...ids(page));
      cursor = page.nextCursor;
    }

    // Full body present, no omission of the final rows.
    expect(collected).toHaveLength(6);
    expect(collected[collected.length - 2]).toMatch(/^verify-07-walk:/);
    expect(new Set(collected).size).toBe(6);
  });

  it("crosses a boundary with head and tail cursors without duplication", () => {
    // More rows than one page; assert head page and tail page are disjoint
    // and their union is exactly the full body once.
    const id = "verify-07-headtail";
    start(id, 4); // 8 display rows, pages of 3.
    const head = readSessionTranscriptHistory(id, { limit: 3 });
    const tail = readSessionTranscriptHistory(id, {
      limit: 3,
      cursor: head.nextCursor,
    });

    expect(head.messages).toHaveLength(3);
    expect(tail.messages).toHaveLength(3);
    const headIds = new Set(ids(head));
    const tailIds = new Set(ids(tail));
    // No row repeated across the page boundary.
    for (const tailId of tailIds) {
      expect(headIds.has(tailId)).toBe(false);
    }
    // The last page is the tail (final body) and shares no identity with head.
    expect(ids(tail)[0]).not.toBe(ids(head)[0]);
  });

  it("never emits the same boundary coverage event on consecutive pages", () => {
    // Force at least two forward pages; boundaryEvent coverage must only
    // appear on the page where the snapshot boundary was crossed.
    const id = "verify-07-boundary";
    start(id, 5); // 10 display rows, pages of 4.
    const p1 = readSessionTranscriptHistory(id, { limit: 4 });
    const p2 = readSessionTranscriptHistory(id, {
      limit: 4,
      cursor: p1.nextCursor,
    });
    const boundaryEvents = (page) =>
      page.coverage?.kind === "snapshot-boundary"
        ? [page.coverage.boundaryEvent]
        : [];

    const events = [...boundaryEvents(p1), ...boundaryEvents(p2)];
    expect(new Set(events).size).toBe(events.length);
  });

  it("keeps the final body rows on the last page instead of dropping them", () => {
    const id = "verify-07-lastpage";
    start(id, 3); // 6 display rows; page size that is not a divisor.
    const first = readSessionTranscriptHistory(id, { limit: 4 });
    const last = readSessionTranscriptHistory(id, {
      limit: 4,
      cursor: first.nextCursor,
    });
    expect(last.messages).toHaveLength(2);
    expect(last.nextCursor).toBeTruthy();
    expect(ids(last).every((rowId) => !ids(first).includes(rowId))).toBe(true);
  });
});

